/* Song/level registry: the logic. The tables are in song_registry_data.inc,
 * generated by tools/gen_song_registry.py from assets-data/. Keep this file
 * free of song data -- add a song by dropping a JSON in assets-data/ and
 * re-running the generator, not by editing here. */

#include "song_registry.h"
#include "bs_dados.h"

#include <stdarg.h>
#include <stdio.h>
#include <string.h>

#include "song_registry_data.inc"

/* The .inc emits the array; this makes the header's SR_LEVEL_COUNT a checked
 * fact rather than a number someone has to remember to update. */
typedef char sr_level_count_must_match[
    (sizeof(g_levels) / sizeof(g_levels[0]) == SR_LEVEL_COUNT) ? 1 : -1];

const sr_level_t *const *sr_levels(void)
{
    return g_levels;
}

unsigned int sr_level_count(void)
{
    return SR_LEVEL_COUNT;
}

unsigned int sr_song_count(void)
{
    unsigned int i, n = 0;
    for (i = 0; i < SR_LEVEL_COUNT; i++)
        n += g_levels[i]->song_count;
    return n;
}

const sr_level_t *sr_level(unsigned int index)
{
    if (index >= SR_LEVEL_COUNT) return NULL;
    return g_levels[index];
}

const sr_level_t *sr_level_by_id(const char *id)
{
    unsigned int i;
    if (!id) return NULL;
    for (i = 0; i < SR_LEVEL_COUNT; i++)
        if (strcmp(g_levels[i]->id, id) == 0) return g_levels[i];
    return NULL;
}

const sr_song_t *sr_song_by_id(const char *id)
{
    unsigned int i, j;
    if (!id) return NULL;
    for (i = 0; i < SR_LEVEL_COUNT; i++) {
        const sr_level_t *l = g_levels[i];
        for (j = 0; j < l->song_count; j++)
            if (strcmp(l->songs[j]->id, id) == 0) return l->songs[j];
    }
    return NULL;
}

int sr_song_has_difficulty(const sr_song_t *s, unsigned int diff)
{
    if (!s) return 0;
    return (s->difficulties & diff) != 0;
}

/* ------------------------------------------------------------------ paths */

/* Join up to five pieces into out, NUL-terminating only when it fits.
 * Returns the length the full path needs, excluding the NUL, so a caller can
 * size a buffer by calling once with out == NULL. The length is measured
 * rather than guessed: no truncation, and no snprintf into a scratch buffer
 * whose size the compiler has to reason about. */
static int join_path(char *out, unsigned int size, const char *const *parts)
{
    size_t total = 0;
    unsigned int i;
    for (i = 0; parts[i]; i++) total += strlen(parts[i]);
    if (total > 0x7fffffff) return -1;

    /* snprintf semantics: write what fits, always NUL-terminate, and return
     * the length the whole path needs. A caller that passes a short buffer
     * therefore still holds a usable (truncated) string and can detect the
     * truncation from the return value, instead of reading uninitialised
     * bytes. */
    if (out && size > 0) {
        size_t at = 0;
        for (i = 0; parts[i] && at + 1 < size; i++) {
            size_t len = strlen(parts[i]);
            if (at + len >= size) len = size - 1 - at;
            memcpy(out + at, parts[i], len);
            at += len;
        }
        out[at] = '\0';
    }
    return (int)total;
}

/* Numero de layouts diferentes em que o chart de uma musica pode estar no
 * pendrive. O original (e o pendrive atual) usa a arvore songs/<id>/<d>.chart,
 * mas o driver de armazenamento USB do PS2 falhou justamente nessa arvore
 * aninhada no console: o arquivo estava la, no caminho exato, e o open()
 * devolvia -1. Como nao da para diagnosticar isso pelo log -- o log so mostra
 * que o open falhou -- a resposta e tentar todos os layouts e REGISTRAR qual
 * abriu. */
#define SR_CHART_LAYOUTS 4u

int sr_chart_layout_count(void)
{
    return (int)SR_CHART_LAYOUTS;
}

int sr_chart_path_at(char *out, unsigned int size, const char *root,
                     const sr_song_t *s, const char *difficulty,
                     unsigned int layout)
{
    const char *parts[8];
    if (!root || !s || !difficulty) return -1;
    if (layout >= SR_CHART_LAYOUTS) return -1;
    /* 0: songs/<id>/<d>.chart   -- o layout do jogo original
     * 1: songs/<id>-<d>.chart   -- plano, um nivel so
     * 2: charts/<id>-<d>.chart  -- plano, outra pasta
     * 3: charts/<id>/<d>.chart  -- arvore, outra pasta
     * Os dois planos existem porque foi num pendrive com arvore aninhada que o
     * usbhdfsd do PS2 nao conseguiu abrir o arquivo. */
    parts[0] = root;
    parts[1] = (layout == 2u || layout == 3u) ? "/charts/" : "/songs/";
    parts[2] = s->id;
    if (layout == 1u || layout == 2u) {
        parts[3] = "-";
        parts[4] = difficulty;
        parts[5] = ".chart";
        parts[6] = NULL;
    } else {
        parts[3] = "/";
        parts[4] = difficulty;
        parts[5] = ".chart";
        parts[6] = NULL;
    }
    return join_path(out, size, parts);
}

int sr_chart_path(char *out, unsigned int size, const char *root,
                  const sr_song_t *s, const char *difficulty)
{
    return sr_chart_path_at(out, size, root, s, difficulty, 0u);
}

int sr_instrumental_path(char *out, unsigned int size, const char *root,
                         const sr_song_t *s)
{
    const char *parts[5];
    if (!root || !s) return -1;
    parts[0] = root; parts[1] = "/songs/"; parts[2] = s->id;
    parts[3] = "/Inst.pcm"; parts[4] = NULL;
    return join_path(out, size, parts);
}

int sr_vocals_path(char *out, unsigned int size, const char *root,
                   const sr_song_t *s, const char *side)
{
    const char *parts[7];
    if (!root || !s || !side) return -1;
    parts[0] = root; parts[1] = "/songs/"; parts[2] = s->id;
    parts[3] = "/Voices-"; parts[4] = side; parts[5] = ".pcm"; parts[6] = NULL;
    return join_path(out, size, parts);
}

int sr_character_path(char *out, unsigned int size, const char *root,
                      const char *character)
{
    const char *parts[5];
    if (!root || !character) return -1;
    parts[0] = root; parts[1] = "/chars/"; parts[2] = character;
    parts[3] = ".pack"; parts[4] = NULL;
    return join_path(out, size, parts);
}

/* -------------------------------------------------------------- validation */

/* A song whose metadata has not been collected reports its characters as
 * PENDENTE. That is a known gap, not a wrong id, and the two are reported
 * differently because they need different actions: fetch a file, versus fix a
 * typo. */
#define SR_PENDING "PENDENTE: falta o metadata da musica"

/* Problem counter shared with sr_validate; the validator resets it on entry. */
static int g_problems;

static int note_style_unknown(sr_note_style_t style);

static int char_exists(const char *id)
{
    unsigned int i;
    if (!id) return 0;
    for (i = 0; i < BS_CHAR_COUNT; i++)
        if (strcmp(bs_chars[i].id, id) == 0) return 1;
    return 0;
}

static int stage_exists(const char *id)
{
    unsigned int i;
    if (!id) return 0;
    for (i = 0; i < BS_STAGE_COUNT; i++)
        if (strcmp(bs_stages[i].id, id) == 0) return 1;
    return 0;
}

static void default_report(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    printf("\n");
}

static void check_song(void (*report)(const char *fmt, ...),
                       const sr_song_t *s, const char *level_id)
{
    if (!s->id || !*s->id) { g_problems++; report("  [%s] musica sem id", level_id); }
    if (!s->display_name || !*s->display_name) { g_problems++; report("  [%s/%s] sem nome", level_id, s->id); }
    if (!s->stage) { g_problems++; report("  [%s/%s] palco: %s", level_id, s->id, SR_PENDING); }
    else if (!stage_exists(s->stage)) { g_problems++; report("  [%s/%s] palco '%s' nao existe em bs_dados.h", level_id, s->id, s->stage); }

    if (!s->player) { g_problems++; report("  [%s/%s] player: %s", level_id, s->id, SR_PENDING); }
    else if (!char_exists(s->player)) { g_problems++; report("  [%s/%s] player '%s' nao existe em bs_dados.h", level_id, s->id, s->player); }

    /* A song may legitimately have no girlfriend slot: the Tutorial does not. */
    if (s->girlfriend && !char_exists(s->girlfriend)) {
        g_problems++;
        report("  [%s/%s] girlfriend '%s' nao existe em bs_dados.h", level_id, s->id, s->girlfriend);
    }

    if (!s->opponent) { g_problems++; report("  [%s/%s] opponent: %s", level_id, s->id, SR_PENDING); }
    else if (!char_exists(s->opponent)) { g_problems++; report("  [%s/%s] opponent '%s' nao existe em bs_dados.h", level_id, s->id, s->opponent); }

    if (!(s->difficulties & SR_DIFF_ALL)) { g_problems++; report("  [%s/%s] nenhuma dificuldade", level_id, s->id); }
    if (!(s->difficulties & SR_DIFF_NORMAL)) { g_problems++; report("  [%s/%s] sem 'normal' (a dificuldade padrao)", level_id, s->id); }
    if (s->bpm <= 0.0f) { g_problems++; report("  [%s/%s] bpm <= 0", level_id, s->id); }
    if (note_style_unknown(s->note_style)) { g_problems++; report("  [%s/%s] noteStyle desconhecido", level_id, s->id); }
}

static int note_style_unknown(sr_note_style_t style)
{
    return style != SR_NOTE_FUNKIN && style != SR_NOTE_PIXEL;
}

int sr_validate(void (*report)(const char *fmt, ...))
{
    unsigned int i, j;
    if (!report) report = default_report;
    g_problems = 0;

    report("song_registry: %u semanas, %u musicas", SR_LEVEL_COUNT, sr_song_count());

    for (i = 0; i < SR_LEVEL_COUNT; i++) {
        const sr_level_t *l = g_levels[i];
        if (!l->id || !*l->id) { g_problems++; report("  semana %u sem id", i); continue; }
        if (l->song_count == 0) { g_problems++; report("  [%s] semana sem musicas", l->id); }
        if (l->song_count > SR_MAX_SONGS_PER_LEVEL) { g_problems++; report("  [%s] %u musicas > limite %d", l->id, l->song_count, SR_MAX_SONGS_PER_LEVEL); }
        if (!l->display_name || !*l->display_name) { g_problems++; report("  [%s] sem nome", l->id); }
        if (!l->title_asset || !*l->title_asset) { g_problems++; report("  [%s] sem titleAsset", l->id); }
        for (j = 0; j < l->song_count; j++) {
            const sr_song_t *s = l->songs[j];
            if (!s) { g_problems++; report("  [%s] musica %u nula", l->id, j); continue; }
            if (sr_song_by_id(s->id) != s) { g_problems++; report("  [%s/%s] id duplicado no registro", l->id, s->id); }
            check_song(report, s, l->id);
        }
    }
    if (g_problems == 0) report("  todos os ids de personagem e palco existem em bs_dados.h");
    return g_problems;
}
